# A single word's offline reference data for the Wordsmith panel.
# Rows are generated by Wordsmith::Importer and are read-only at runtime.
class WordsmithEntry < ApplicationRecord
  def parsed_senses
    senses.present? ? JSON.parse(senses) : []
  end

  def parsed_related
    related.present? ? JSON.parse(related) : []
  end
end
